insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (1, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>私</u>は がくせいです。', '["わたし","あなた","かれ","どなた"]'::jsonb, 0, '私 dibaca “わたし” dan berarti saya.', 'Bab 1–5 · Mondai 1 No.1', 'kanji:私'),
  (1, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あのかたは <u>会社員</u>です。', '["かいしゃいん","ぎんこういん","けんきゅうしゃ","きょうし"]'::jsonb, 0, '会社員 dibaca “かいしゃいん” dan berarti pegawai perusahaan.', 'Bab 1–5 · Mondai 1 No.2', 'kanji:会社員'),
  (1, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>韓国</u>から きました。', '["かんこく","ちゅうごく","にほん","だいがく"]'::jsonb, 0, '韓国 dibaca “かんこく” dan berarti Korea.', 'Bab 1–5 · Mondai 1 No.3', 'kanji:韓国'),
  (1, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの <u>辞書</u>です。', '["じしょ","ざっし","しんぶん","めいし"]'::jsonb, 0, '辞書 dibaca “じしょ” dan berarti kamus.', 'Bab 1–5 · Mondai 1 No.4', 'kanji:辞書'),
  (1, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'その <u>新聞</u>は わたしのです。', '["しんぶん","ざっし","てちょう","めいし"]'::jsonb, 0, '新聞 dibaca “しんぶん” dan berarti koran.', 'Bab 1–5 · Mondai 1 No.5', 'kanji:新聞'),
  (1, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>会議室</u>は あそこです。', '["かいぎしつ","じむしょ","きょうしつ","しょくどう"]'::jsonb, 0, '会議室 dibaca “かいぎしつ” dan berarti ruang rapat.', 'Bab 1–5 · Mondai 1 No.6', 'kanji:会議室'),
  (1, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'エレベーターは <u>何階</u>ですか。', '["なんがい","なんかい","なんえん","なんにち"]'::jsonb, 0, '何階 dibaca “なんがい” dan berarti lantai berapa.', 'Bab 1–5 · Mondai 1 No.7', 'kanji:何階'),
  (1, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ 6じに <u>起きます</u>。', '["おきます","ねます","はたらきます","やすみます"]'::jsonb, 0, '起きます dibaca “おきます” dan berarti bangun tidur.', 'Bab 1–5 · Mondai 1 No.8', 'kanji:起きます'),
  (1, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは <u>何曜日</u>ですか。', '["なんようび","なんじ","なんにち","なんがつ"]'::jsonb, 0, '何曜日 dibaca “なんようび” dan berarti hari apa.', 'Bab 1–5 · Mondai 1 No.9', 'kanji:何曜日'),
  (1, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>午後</u>は かいぎです。', '["ごご","ごぜん","いま","まいにち"]'::jsonb, 0, '午後 dibaca “ごご” dan berarti sore/siang setelah jam 12.', 'Bab 1–5 · Mondai 1 No.10', 'kanji:午後'),
  (1, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あの <u>がくせい</u>は わたしの ともだちです。', '["学生","先生","医者","会社員"]'::jsonb, 0, 'がくせい ditulis 学生, berarti pelajar/mahasiswa.', 'Bab 1–5 · Mondai 2 No.11', 'kanji:学生'),
  (1, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの <u>とけい</u>です。', '["時計","眼鏡","傘","鞄"]'::jsonb, 0, 'とけい ditulis 時計, berarti jam/arloji.', 'Bab 1–5 · Mondai 2 No.12', 'kanji:時計'),
  (1, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'その <u>えんぴつ</u>は だれのですか。', '["鉛筆","雑誌","手帳","名刺"]'::jsonb, 0, 'えんぴつ ditulis 鉛筆, berarti pensil.', 'Bab 1–5 · Mondai 2 No.13', 'kanji:鉛筆'),
  (1, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>かいしゃ</u>は どこですか。', '["会社","事務所","教室","食堂"]'::jsonb, 0, 'かいしゃ ditulis 会社, berarti perusahaan.', 'Bab 1–5 · Mondai 2 No.14', 'kanji:会社'),
  (1, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ 7じに <u>おきます</u>。', '["起きます","寝ます","働きます","終わります"]'::jsonb, 0, 'おきます ditulis 起きます, berarti bangun tidur.', 'Bab 1–5 · Mondai 2 No.15', 'kanji:起きます'),
  (1, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>にちようび</u>は やすみです。', '["日曜日","土曜日","月曜日","金曜日"]'::jsonb, 0, 'にちようび ditulis 日曜日, berarti hari Minggu.', 'Bab 1–5 · Mondai 2 No.16', 'kanji:日曜日'),
  (1, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>でんしゃ</u>で がっこうへ いきます。', '["電車","自転車","飛行機","地下鉄"]'::jsonb, 0, 'でんしゃ ditulis 電車, berarti kereta listrik.', 'Bab 1–5 · Mondai 2 No.17', 'kanji:電車'),
  (1, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>おてあらい</u>は どこですか。', '["お手洗い","事務所","教室","食堂"]'::jsonb, 0, 'おてあらい ditulis お手洗い, berarti kamar kecil/WC.', 'Bab 1–5 · Mondai 2 No.18', 'kanji:お手洗い'),
  (1, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>ともだち</u>と えいがを みます。', '["友達","家族","先生","会社員"]'::jsonb, 0, 'ともだち ditulis 友達, berarti teman.', 'Bab 1–5 · Mondai 2 No.19', 'kanji:友達'),
  (1, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>らいしゅう</u> にほんへ いきます。', '["来週","先週","今週","来年"]'::jsonb, 0, 'らいしゅう ditulis 来週, berarti minggu depan.', 'Bab 1–5 · Mondai 2 No.20', 'kanji:来週'),
  (1, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>ミラーです。</span></div><small>Petunjuk arti: “Saya adalah Miller.”</small>', '["②→①→③","①→②→③","②→③→①","①→③→②"]'::jsonb, 0, 'Urutan yang benar: ②わたし→①は→③ミラーです。 は menandai topik kalimat, diletakkan tepat setelah kata benda yang menjadi topik (Pel.1).', 'Bab 1–5 · Mondai 3 No.21', 'materi:book1:0:0'),
  (1, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ほんです。</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>これは</span><span class="arrange-chip"><b>④</b>の</span></div><small>Petunjuk arti: “Ini buku saya.”</small>', '["③→②→④→①","②→③→④→①","③→④→②→①","③→②→①→④"]'::jsonb, 0, 'Urutan yang benar: ③これは→②わたし→④の→①ほんです。 の menghubungkan dua kata benda untuk kepemilikan, diletakkan setelah pemilik dan sebelum benda yang dimiliki (Pel.2).', 'Bab 1–5 · Mondai 3 No.22', 'materi:book1:1:0'),
  (1, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>も</span><span class="arrange-chip"><b>②</b>あなた</span><span class="arrange-chip"><b>③</b>がくせいですか。</span></div><small>Petunjuk arti: “Apakah Anda juga pelajar?”</small>', '["②→①→③","①→②→③","②→③→①","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ②あなた→①も→③がくせいですか。 も berarti “juga”, menggantikan は saat topik kedua memiliki predikat yang sama (Pel.2).', 'Bab 1–5 · Mondai 3 No.23', 'materi:book1:1:0'),
  (1, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>か</span><span class="arrange-chip"><b>②</b>あなたは</span><span class="arrange-chip"><b>③</b>がくせいです</span></div><small>Petunjuk arti: “Apakah Anda pelajar?”</small>', '["②→③→①","③→②→①","②→①→③","①→②→③"]'::jsonb, 0, 'Urutan yang benar: ②あなたは→③がくせいです→①か。 か diletakkan di akhir kalimat untuk membuat kalimat tanya, tanpa mengubah susunan kata sebelumnya (Pel.1).', 'Bab 1–5 · Mondai 3 No.24', 'materi:book1:0:0'),
  (1, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ねます。</span><span class="arrange-chip"><b>②</b>まいばん</span><span class="arrange-chip"><b>③</b>11じ</span><span class="arrange-chip"><b>④</b>に</span></div><small>Petunjuk arti: “Setiap malam saya tidur jam 11.”</small>', '["②→③→④→①","③→②→④→①","②→④→③→①","②→③→①→④"]'::jsonb, 0, 'Urutan yang benar: ②まいばん→③11じ→④に→①ねます。 に menandai waktu yang spesifik seperti jam, diletakkan tepat setelah keterangan jam (Pel.4).', 'Bab 1–5 · Mondai 3 No.25', 'materi:book1:3:0'),
  (1, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>いきます。</span><span class="arrange-chip"><b>②</b>らいしゅう</span><span class="arrange-chip"><b>③</b>きょうと</span><span class="arrange-chip"><b>④</b>へ</span></div><small>Petunjuk arti: “Minggu depan saya pergi ke Kyoto.”</small>', '["②→③→④→①","③→②→④→①","②→④→③→①","②→③→①→④"]'::jsonb, 0, 'Urutan yang benar: ②らいしゅう→③きょうと→④へ→①いきます。 へ menandai arah atau tujuan perpindahan, diletakkan tepat setelah nama tempat tujuan (Pel.5).', 'Bab 1–5 · Mondai 3 No.26', 'materi:book1:4:0'),
  (1, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>でんしゃ</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>わたしは</span><span class="arrange-chip"><b>④</b>がっこうへ いきます。</span></div><small>Petunjuk arti: “Saya pergi ke sekolah naik kereta.”</small>', '["③→①→②→④","①→③→②→④","③→②→①→④","③→①→④→②"]'::jsonb, 0, 'Urutan yang benar: ③わたしは→①でんしゃ→②で→④がっこうへ いきます。 で menandai alat transportasi yang dipakai, diletakkan tepat setelah nama kendaraannya (Pel.5).', 'Bab 1–5 · Mondai 3 No.27', 'materi:book1:4:0'),
  (1, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きんようびまで</span><span class="arrange-chip"><b>②</b>から</span><span class="arrange-chip"><b>③</b>はたらきます。</span><span class="arrange-chip"><b>④</b>げつようび</span></div><small>Petunjuk arti: “Saya bekerja dari hari Senin sampai hari Jumat.”</small>', '["④→②→①→③","②→④→①→③","④→①→②→③","④→②→③→①"]'::jsonb, 0, 'Urutan yang benar: ④げつようび→②から→①きんようびまで→③はたらきます。 から menunjukkan titik mulai, dipasangkan dengan まで untuk titik akhir (Pel.4).', 'Bab 1–5 · Mondai 3 No.28', 'materi:book1:3:0'),
  (1, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ぎんこうは</span><span class="arrange-chip"><b>②</b>9じから</span><span class="arrange-chip"><b>③</b>3じ</span><span class="arrange-chip"><b>④</b>です。</span><span class="arrange-chip"><b>⑤</b>まで</span></div><small>Petunjuk arti: “Bank buka dari jam 9 sampai jam 3.”</small>', '["①→②→③→⑤→④","②→①→③→⑤→④","①→③→②→⑤→④","①→②→⑤→③→④"]'::jsonb, 0, 'Urutan yang benar: ①ぎんこうは→②9じから→③3じ→⑤まで→④です。 まで menunjukkan batas akhir waktu, dipasangkan dengan から (Pel.4).', 'Bab 1–5 · Mondai 3 No.29', 'materi:book1:3:0'),
  (1, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>かえります。</span><span class="arrange-chip"><b>②</b>と</span><span class="arrange-chip"><b>③</b>ともだち</span></div><small>Petunjuk arti: “Saya pulang bersama teman.”</small>', '["③→②→①","②→③→①","③→①→②","①→②→③"]'::jsonb, 0, 'Urutan yang benar: ③ともだち→②と→①かえります。 と menunjukkan teman yang menyertai suatu kegiatan (Pel.5).', 'Bab 1–5 · Mondai 3 No.30', 'materi:book1:4:0'),
  (1, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>がくせいです。</span><span class="arrange-chip"><b>②</b>わたしは</span><span class="arrange-chip"><b>③</b>IMCの</span></div><small>Petunjuk arti: “Saya adalah pelajar IMC.”</small>', '["②→③→①","③→②→①","②→①→③","①→③→②"]'::jsonb, 0, 'Urutan yang benar: ②わたしは→③IMCの→①がくせいです。 Pola N1は N2の N3です: IMCの menerangkan がくせい, jadi “わたしはIMCのがくせいです” berarti “Saya pelajar IMC” (Pel.1–2).', 'Bab 1–5 · Mondai 4 No.31', 'materi:book1:1:0'),
  (1, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>です。</span><span class="arrange-chip"><b>②</b>あそこ</span><span class="arrange-chip"><b>③</b>おてあらいは</span></div><small>Petunjuk arti: “Kamar kecil ada di sana.”</small>', '["③→②→①","②→③→①","③→①→②","②→①→③"]'::jsonb, 0, 'Urutan yang benar: ③おてあらいは→②あそこ→①です。 Pola Kata Benda（tempat）は tempat です dipakai untuk menyatakan lokasi (Pel.3): “おてあらいはあそこです” berarti “Kamar kecil ada di sana.”', 'Bab 1–5 · Mondai 4 No.32', 'materi:book1:2:0'),
  (1, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おきます。</span><span class="arrange-chip"><b>②</b>まいあさ</span><span class="arrange-chip"><b>③</b>6じに</span></div><small>Petunjuk arti: “Setiap pagi saya bangun jam 6.”</small>', '["②→③→①","③→②→①","②→①→③","①→③→②"]'::jsonb, 0, 'Urutan yang benar: ②まいあさ→③6じに→①おきます。 Keterangan waktu umum (まいあさ) diikuti waktu spesifik+に, lalu kata kerja di akhir kalimat (Pel.4).', 'Bab 1–5 · Mondai 4 No.33', 'materi:book1:3:0'),
  (1, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きょうとへ</span><span class="arrange-chip"><b>②</b>いきます。</span><span class="arrange-chip"><b>③</b>でんしゃで</span></div><small>Petunjuk arti: “Saya pergi ke Kyoto naik kereta.”</small>', '["③→①→②","①→③→②","③→②→①","②→③→①"]'::jsonb, 0, 'Urutan yang benar: ③でんしゃで→①きょうとへ→②いきます。 Alat transportasi+で, tujuan+へ, lalu kata kerja di akhir kalimat (Pel.5).', 'Bab 1–5 · Mondai 4 No.34', 'materi:book1:4:0'),
  (1, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>かえります。</span><span class="arrange-chip"><b>②</b>かぞくと</span><span class="arrange-chip"><b>③</b>わたしは</span></div><small>Petunjuk arti: “Saya pulang bersama keluarga.”</small>', '["③→②→①","②→③→①","③→①→②","②→①→③"]'::jsonb, 0, 'Urutan yang benar: ③わたしは→②かぞくと→①かえります。 と menandai orang yang menyertai suatu kegiatan (Pel.5).', 'Bab 1–5 · Mondai 4 No.35', 'materi:book1:4:0'),
  (1, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ミラーさんは　IMCの　会社員です。学生じゃ　ありません。これは　ミラーさんの　傘ですか。……いいえ、違います。それは　山田さんのです。<br><small>この　傘は　だれのですか。</small>', '["ミラーさんの","山田さんの","IMCの","学生の"]'::jsonb, 1, 'Cerita menjawab langsung: “Apakah ini payung Miller?……Bukan, itu payung Yamada.” の menggantikan Kata Benda yang sudah disebut (Pel.1–2), jadi 山田さんの berarti “punya Sdr. Yamada”.', 'Bab 1–5 · Soal Cerita No.36', 'materi:book1:1:0'),
  (1, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'この　本は　わたしのです。あの　コンピューターは　どこの　コンピューターですか。……日本の　コンピューターです。会社の　事務所は　2階です。<br><small>事務所は　どこですか。</small>', '["1階","2階","3階","4階"]'::jsonb, 1, 'Kalimat terakhir cerita menyebutkan “Kantor perusahaan di lantai 2”, memakai pola Kata Benda は tempat です (Pel.3) untuk menyatakan lokasi.', 'Bab 1–5 · Soal Cerita No.37', 'materi:book1:2:0'),
  (1, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'お手洗いは　あそこです。銀行は　9時から　3時までです。わたしは　まいあさ　6時に　おきます。<br><small>銀行は　何時からですか。</small>', '["7時","8時","9時","10時"]'::jsonb, 2, 'Cerita menyatakan “Bank dari pukul 9 sampai pukul 3”, memakai pola～から～まで (Pel.4) untuk titik mulai dan titik akhir waktu.', 'Bab 1–5 · Soal Cerita No.38', 'materi:book1:3:0'),
  (1, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きのう　勉強しませんでした。あした　京都へ　行きます。電車で　行きます。<br><small>何で　京都へ　行きますか。</small>', '["バス","タクシー","電車","歩いて"]'::jsonb, 2, 'Kalimat terakhir cerita menyebutkan “Pergi dengan kereta rel listrik”, memakai pola Kata Benda（kendaraan）で行きます (Pel.5) untuk sarana transportasi.', 'Bab 1–5 · Soal Cerita No.39', 'materi:book1:4:0'),
  (1, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', '先週　どこ［へ］も　行きませんでした。今週の　日曜日、家族と　京都へ　行きます。……いいですね。<br><small>だれと　京都へ　行きますか。</small>', '["一人で","友達と","家族と","先生と"]'::jsonb, 2, 'Cerita menyebutkan “Bersama keluarga pergi ke Kyoto”, memakai pola Kata Benda（orang）と Kata Kerja (Pel.5) untuk menyatakan teman melakukan sesuatu.', 'Bab 1–5 · Soal Cerita No.40', 'materi:book1:4:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (1, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>私</u>は がくせいです。', '["わたし","あなた","かれ","どなた"]'::jsonb, 0, '私 dibaca “わたし” dan berarti saya.', 'Bab 1–5 · Mondai 1 No.1', 'kanji:私'),
  (1, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あのかたは <u>会社員</u>です。', '["かいしゃいん","ぎんこういん","けんきゅうしゃ","きょうし"]'::jsonb, 0, '会社員 dibaca “かいしゃいん” dan berarti pegawai perusahaan.', 'Bab 1–5 · Mondai 1 No.2', 'kanji:会社員'),
  (1, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>韓国</u>から きました。', '["かんこく","ちゅうごく","にほん","だいがく"]'::jsonb, 0, '韓国 dibaca “かんこく” dan berarti Korea.', 'Bab 1–5 · Mondai 1 No.3', 'kanji:韓国'),
  (1, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの <u>辞書</u>です。', '["じしょ","ざっし","しんぶん","めいし"]'::jsonb, 0, '辞書 dibaca “じしょ” dan berarti kamus.', 'Bab 1–5 · Mondai 1 No.4', 'kanji:辞書'),
  (1, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'その <u>新聞</u>は わたしのです。', '["しんぶん","ざっし","てちょう","めいし"]'::jsonb, 0, '新聞 dibaca “しんぶん” dan berarti koran.', 'Bab 1–5 · Mondai 1 No.5', 'kanji:新聞'),
  (1, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>会議室</u>は あそこです。', '["かいぎしつ","じむしょ","きょうしつ","しょくどう"]'::jsonb, 0, '会議室 dibaca “かいぎしつ” dan berarti ruang rapat.', 'Bab 1–5 · Mondai 1 No.6', 'kanji:会議室'),
  (1, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'エレベーターは <u>何階</u>ですか。', '["なんがい","なんかい","なんえん","なんにち"]'::jsonb, 0, '何階 dibaca “なんがい” dan berarti lantai berapa.', 'Bab 1–5 · Mondai 1 No.7', 'kanji:何階'),
  (1, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ 6じに <u>起きます</u>。', '["おきます","ねます","はたらきます","やすみます"]'::jsonb, 0, '起きます dibaca “おきます” dan berarti bangun tidur.', 'Bab 1–5 · Mondai 1 No.8', 'kanji:起きます'),
  (1, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは <u>何曜日</u>ですか。', '["なんようび","なんじ","なんにち","なんがつ"]'::jsonb, 0, '何曜日 dibaca “なんようび” dan berarti hari apa.', 'Bab 1–5 · Mondai 1 No.9', 'kanji:何曜日'),
  (1, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>午後</u>は かいぎです。', '["ごご","ごぜん","いま","まいにち"]'::jsonb, 0, '午後 dibaca “ごご” dan berarti sore/siang setelah jam 12.', 'Bab 1–5 · Mondai 1 No.10', 'kanji:午後'),
  (1, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あの <u>がくせい</u>は わたしの ともだちです。', '["学生","先生","医者","会社員"]'::jsonb, 0, 'がくせい ditulis 学生, berarti pelajar/mahasiswa.', 'Bab 1–5 · Mondai 2 No.11', 'kanji:学生'),
  (1, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'これは わたしの <u>とけい</u>です。', '["時計","眼鏡","傘","鞄"]'::jsonb, 0, 'とけい ditulis 時計, berarti jam/arloji.', 'Bab 1–5 · Mondai 2 No.12', 'kanji:時計'),
  (1, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'その <u>えんぴつ</u>は だれのですか。', '["鉛筆","雑誌","手帳","名刺"]'::jsonb, 0, 'えんぴつ ditulis 鉛筆, berarti pensil.', 'Bab 1–5 · Mondai 2 No.13', 'kanji:鉛筆'),
  (1, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>かいしゃ</u>は どこですか。', '["会社","事務所","教室","食堂"]'::jsonb, 0, 'かいしゃ ditulis 会社, berarti perusahaan.', 'Bab 1–5 · Mondai 2 No.14', 'kanji:会社'),
  (1, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ 7じに <u>おきます</u>。', '["起きます","寝ます","働きます","終わります"]'::jsonb, 0, 'おきます ditulis 起きます, berarti bangun tidur.', 'Bab 1–5 · Mondai 2 No.15', 'kanji:起きます'),
  (1, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>にちようび</u>は やすみです。', '["日曜日","土曜日","月曜日","金曜日"]'::jsonb, 0, 'にちようび ditulis 日曜日, berarti hari Minggu.', 'Bab 1–5 · Mondai 2 No.16', 'kanji:日曜日'),
  (1, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>でんしゃ</u>で がっこうへ いきます。', '["電車","自転車","飛行機","地下鉄"]'::jsonb, 0, 'でんしゃ ditulis 電車, berarti kereta listrik.', 'Bab 1–5 · Mondai 2 No.17', 'kanji:電車'),
  (1, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>おてあらい</u>は どこですか。', '["お手洗い","事務所","教室","食堂"]'::jsonb, 0, 'おてあらい ditulis お手洗い, berarti kamar kecil/WC.', 'Bab 1–5 · Mondai 2 No.18', 'kanji:お手洗い'),
  (1, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>ともだち</u>と えいがを みます。', '["友達","家族","先生","会社員"]'::jsonb, 0, 'ともだち ditulis 友達, berarti teman.', 'Bab 1–5 · Mondai 2 No.19', 'kanji:友達'),
  (1, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>らいしゅう</u> にほんへ いきます。', '["来週","先週","今週","来年"]'::jsonb, 0, 'らいしゅう ditulis 来週, berarti minggu depan.', 'Bab 1–5 · Mondai 2 No.20', 'kanji:来週'),
  (1, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>ミラーです。</span></div><small>Petunjuk arti: “Saya adalah Miller.”</small>', '["②→①→③","①→②→③","②→③→①","①→③→②"]'::jsonb, 0, 'Urutan yang benar: ②わたし→①は→③ミラーです。 は menandai topik kalimat, diletakkan tepat setelah kata benda yang menjadi topik (Pel.1).', 'Bab 1–5 · Mondai 3 No.21', 'materi:book1:0:0'),
  (1, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ほんです。</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>これは</span><span class="arrange-chip"><b>④</b>の</span></div><small>Petunjuk arti: “Ini buku saya.”</small>', '["③→②→④→①","②→③→④→①","③→④→②→①","③→②→①→④"]'::jsonb, 0, 'Urutan yang benar: ③これは→②わたし→④の→①ほんです。 の menghubungkan dua kata benda untuk kepemilikan, diletakkan setelah pemilik dan sebelum benda yang dimiliki (Pel.2).', 'Bab 1–5 · Mondai 3 No.22', 'materi:book1:1:0'),
  (1, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>も</span><span class="arrange-chip"><b>②</b>あなた</span><span class="arrange-chip"><b>③</b>がくせいですか。</span></div><small>Petunjuk arti: “Apakah Anda juga pelajar?”</small>', '["②→①→③","①→②→③","②→③→①","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ②あなた→①も→③がくせいですか。 も berarti “juga”, menggantikan は saat topik kedua memiliki predikat yang sama (Pel.2).', 'Bab 1–5 · Mondai 3 No.23', 'materi:book1:1:0'),
  (1, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>か</span><span class="arrange-chip"><b>②</b>あなたは</span><span class="arrange-chip"><b>③</b>がくせいです</span></div><small>Petunjuk arti: “Apakah Anda pelajar?”</small>', '["②→③→①","③→②→①","②→①→③","①→②→③"]'::jsonb, 0, 'Urutan yang benar: ②あなたは→③がくせいです→①か。 か diletakkan di akhir kalimat untuk membuat kalimat tanya, tanpa mengubah susunan kata sebelumnya (Pel.1).', 'Bab 1–5 · Mondai 3 No.24', 'materi:book1:0:0'),
  (1, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ねます。</span><span class="arrange-chip"><b>②</b>まいばん</span><span class="arrange-chip"><b>③</b>11じ</span><span class="arrange-chip"><b>④</b>に</span></div><small>Petunjuk arti: “Setiap malam saya tidur jam 11.”</small>', '["②→③→④→①","③→②→④→①","②→④→③→①","②→③→①→④"]'::jsonb, 0, 'Urutan yang benar: ②まいばん→③11じ→④に→①ねます。 に menandai waktu yang spesifik seperti jam, diletakkan tepat setelah keterangan jam (Pel.4).', 'Bab 1–5 · Mondai 3 No.25', 'materi:book1:3:0'),
  (1, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>いきます。</span><span class="arrange-chip"><b>②</b>らいしゅう</span><span class="arrange-chip"><b>③</b>きょうと</span><span class="arrange-chip"><b>④</b>へ</span></div><small>Petunjuk arti: “Minggu depan saya pergi ke Kyoto.”</small>', '["②→③→④→①","③→②→④→①","②→④→③→①","②→③→①→④"]'::jsonb, 0, 'Urutan yang benar: ②らいしゅう→③きょうと→④へ→①いきます。 へ menandai arah atau tujuan perpindahan, diletakkan tepat setelah nama tempat tujuan (Pel.5).', 'Bab 1–5 · Mondai 3 No.26', 'materi:book1:4:0'),
  (1, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>でんしゃ</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>わたしは</span><span class="arrange-chip"><b>④</b>がっこうへ いきます。</span></div><small>Petunjuk arti: “Saya pergi ke sekolah naik kereta.”</small>', '["③→①→②→④","①→③→②→④","③→②→①→④","③→①→④→②"]'::jsonb, 0, 'Urutan yang benar: ③わたしは→①でんしゃ→②で→④がっこうへ いきます。 で menandai alat transportasi yang dipakai, diletakkan tepat setelah nama kendaraannya (Pel.5).', 'Bab 1–5 · Mondai 3 No.27', 'materi:book1:4:0'),
  (1, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きんようびまで</span><span class="arrange-chip"><b>②</b>から</span><span class="arrange-chip"><b>③</b>はたらきます。</span><span class="arrange-chip"><b>④</b>げつようび</span></div><small>Petunjuk arti: “Saya bekerja dari hari Senin sampai hari Jumat.”</small>', '["④→②→①→③","②→④→①→③","④→①→②→③","④→②→③→①"]'::jsonb, 0, 'Urutan yang benar: ④げつようび→②から→①きんようびまで→③はたらきます。 から menunjukkan titik mulai, dipasangkan dengan まで untuk titik akhir (Pel.4).', 'Bab 1–5 · Mondai 3 No.28', 'materi:book1:3:0'),
  (1, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ぎんこうは</span><span class="arrange-chip"><b>②</b>9じから</span><span class="arrange-chip"><b>③</b>3じ</span><span class="arrange-chip"><b>④</b>です。</span><span class="arrange-chip"><b>⑤</b>まで</span></div><small>Petunjuk arti: “Bank buka dari jam 9 sampai jam 3.”</small>', '["①→②→③→⑤→④","②→①→③→⑤→④","①→③→②→⑤→④","①→②→⑤→③→④"]'::jsonb, 0, 'Urutan yang benar: ①ぎんこうは→②9じから→③3じ→⑤まで→④です。 まで menunjukkan batas akhir waktu, dipasangkan dengan から (Pel.4).', 'Bab 1–5 · Mondai 3 No.29', 'materi:book1:3:0'),
  (1, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>かえります。</span><span class="arrange-chip"><b>②</b>と</span><span class="arrange-chip"><b>③</b>ともだち</span></div><small>Petunjuk arti: “Saya pulang bersama teman.”</small>', '["③→②→①","②→③→①","③→①→②","①→②→③"]'::jsonb, 0, 'Urutan yang benar: ③ともだち→②と→①かえります。 と menunjukkan teman yang menyertai suatu kegiatan (Pel.5).', 'Bab 1–5 · Mondai 3 No.30', 'materi:book1:4:0'),
  (1, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>がくせいです。</span><span class="arrange-chip"><b>②</b>わたしは</span><span class="arrange-chip"><b>③</b>IMCの</span></div><small>Petunjuk arti: “Saya adalah pelajar IMC.”</small>', '["②→③→①","③→②→①","②→①→③","①→③→②"]'::jsonb, 0, 'Urutan yang benar: ②わたしは→③IMCの→①がくせいです。 Pola N1は N2の N3です: IMCの menerangkan がくせい, jadi “わたしはIMCのがくせいです” berarti “Saya pelajar IMC” (Pel.1–2).', 'Bab 1–5 · Mondai 4 No.31', 'materi:book1:1:0'),
  (1, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>です。</span><span class="arrange-chip"><b>②</b>あそこ</span><span class="arrange-chip"><b>③</b>おてあらいは</span></div><small>Petunjuk arti: “Kamar kecil ada di sana.”</small>', '["③→②→①","②→③→①","③→①→②","②→①→③"]'::jsonb, 0, 'Urutan yang benar: ③おてあらいは→②あそこ→①です。 Pola Kata Benda（tempat）は tempat です dipakai untuk menyatakan lokasi (Pel.3): “おてあらいはあそこです” berarti “Kamar kecil ada di sana.”', 'Bab 1–5 · Mondai 4 No.32', 'materi:book1:2:0'),
  (1, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おきます。</span><span class="arrange-chip"><b>②</b>まいあさ</span><span class="arrange-chip"><b>③</b>6じに</span></div><small>Petunjuk arti: “Setiap pagi saya bangun jam 6.”</small>', '["②→③→①","③→②→①","②→①→③","①→③→②"]'::jsonb, 0, 'Urutan yang benar: ②まいあさ→③6じに→①おきます。 Keterangan waktu umum (まいあさ) diikuti waktu spesifik+に, lalu kata kerja di akhir kalimat (Pel.4).', 'Bab 1–5 · Mondai 4 No.33', 'materi:book1:3:0'),
  (1, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きょうとへ</span><span class="arrange-chip"><b>②</b>いきます。</span><span class="arrange-chip"><b>③</b>でんしゃで</span></div><small>Petunjuk arti: “Saya pergi ke Kyoto naik kereta.”</small>', '["③→①→②","①→③→②","③→②→①","②→③→①"]'::jsonb, 0, 'Urutan yang benar: ③でんしゃで→①きょうとへ→②いきます。 Alat transportasi+で, tujuan+へ, lalu kata kerja di akhir kalimat (Pel.5).', 'Bab 1–5 · Mondai 4 No.34', 'materi:book1:4:0'),
  (1, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>かえります。</span><span class="arrange-chip"><b>②</b>かぞくと</span><span class="arrange-chip"><b>③</b>わたしは</span></div><small>Petunjuk arti: “Saya pulang bersama keluarga.”</small>', '["③→②→①","②→③→①","③→①→②","②→①→③"]'::jsonb, 0, 'Urutan yang benar: ③わたしは→②かぞくと→①かえります。 と menandai orang yang menyertai suatu kegiatan (Pel.5).', 'Bab 1–5 · Mondai 4 No.35', 'materi:book1:4:0'),
  (1, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ミラーさんは　IMCの　会社員です。学生じゃ　ありません。これは　ミラーさんの　傘ですか。……いいえ、違います。それは　山田さんのです。<br><small>この　傘は　だれのですか。</small>', '["ミラーさんの","山田さんの","IMCの","学生の"]'::jsonb, 1, 'Cerita menjawab langsung: “Apakah ini payung Miller?……Bukan, itu payung Yamada.” の menggantikan Kata Benda yang sudah disebut (Pel.1–2), jadi 山田さんの berarti “punya Sdr. Yamada”.', 'Bab 1–5 · Soal Cerita No.36', 'materi:book1:1:0'),
  (1, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'この　本は　わたしのです。あの　コンピューターは　どこの　コンピューターですか。……日本の　コンピューターです。会社の　事務所は　2階です。<br><small>事務所は　どこですか。</small>', '["1階","2階","3階","4階"]'::jsonb, 1, 'Kalimat terakhir cerita menyebutkan “Kantor perusahaan di lantai 2”, memakai pola Kata Benda は tempat です (Pel.3) untuk menyatakan lokasi.', 'Bab 1–5 · Soal Cerita No.37', 'materi:book1:2:0'),
  (1, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'お手洗いは　あそこです。銀行は　9時から　3時までです。わたしは　まいあさ　6時に　おきます。<br><small>銀行は　何時からですか。</small>', '["7時","8時","9時","10時"]'::jsonb, 2, 'Cerita menyatakan “Bank dari pukul 9 sampai pukul 3”, memakai pola～から～まで (Pel.4) untuk titik mulai dan titik akhir waktu.', 'Bab 1–5 · Soal Cerita No.38', 'materi:book1:3:0'),
  (1, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きのう　勉強しませんでした。あした　京都へ　行きます。電車で　行きます。<br><small>何で　京都へ　行きますか。</small>', '["バス","タクシー","電車","歩いて"]'::jsonb, 2, 'Kalimat terakhir cerita menyebutkan “Pergi dengan kereta rel listrik”, memakai pola Kata Benda（kendaraan）で行きます (Pel.5) untuk sarana transportasi.', 'Bab 1–5 · Soal Cerita No.39', 'materi:book1:4:0'),
  (1, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', '先週　どこ［へ］も　行きませんでした。今週の　日曜日、家族と　京都へ　行きます。……いいですね。<br><small>だれと　京都へ　行きますか。</small>', '["一人で","友達と","家族と","先生と"]'::jsonb, 2, 'Cerita menyebutkan “Bersama keluarga pergi ke Kyoto”, memakai pola Kata Benda（orang）と Kata Kerja (Pel.5) untuk menyatakan teman melakukan sesuatu.', 'Bab 1–5 · Soal Cerita No.40', 'materi:book1:4:0');
